<script setup lang="ts">
import { ref } from 'vue'
import { useRouter } from 'vue-router'
import { api, attempt, saveSession, guest, user } from '../services/api'
import { useMeetingStore } from '../stores/meeting'
const router=useRouter(), store=useMeetingStore(), phone=ref(''), password=ref(''), nickname=ref(store.profileName), busy=ref(false), registering=ref(false)
async function login(asGuest=false) { busy.value=true; try { const result=asGuest?await guest(nickname.value):await api(registering.value?'/user/register':'/user/login','POST',registering.value?{phone:phone.value,password:password.value,nickname:nickname.value}:{phone:phone.value,password:password.value},false); saveSession(result); store.profileName=result.user.nickname; await store.refresh(); router.push(result.user.role==='admin'?'/admin':'/') } catch(e) { await attempt(async()=>{ throw e }) } finally { busy.value=false } }
function logout(){ sessionStorage.clear(); location.assign('/') }
</script>
<template><main class="form-page account-page"><RouterLink to="/" class="back-link">← 返回首页</RouterLink><h1>连接你的会议空间</h1><section class="panel-card schedule-form"><h2>{{ registering ? '手机号注册' : '账号登录' }}</h2><p>手机号注册无需短信验证；也可以游客身份临时入会。</p><form @submit.prevent="login()"><label class="field"><span>手机号</span><input v-model="phone" autocomplete="tel" inputmode="numeric" pattern="[0-9]{11}" maxlength="11" required /></label><label v-if="registering" class="field"><span>昵称</span><input v-model="nickname" maxlength="30" required /></label><label class="field"><span>密码（至少8位）</span><input v-model="password" type="password" :autocomplete="registering?'new-password':'current-password'" minlength="8" required /></label><button class="primary-button" :disabled="busy">{{ registering ? '创建账号' : '登录' }}</button></form><button class="text-button" @click="registering=!registering">{{ registering ? '已有账号？立即登录' : '手机号注册' }}</button><hr /><form @submit.prevent="login(true)"><label class="field"><span>游客昵称</span><input v-model="nickname" maxlength="30" required /></label><button class="secondary-button" :disabled="busy">使用游客身份</button></form><button v-if="user" class="text-button" @click="logout">退出当前身份</button></section></main></template>
